# 깊은 강호의 외전: 같은 줄거리에 붙는 문장, 그 강호에서만 열리는 길, 마지막 상대의 괴공
from dsl import *
DEEP_ORIGIN={}; BOSS={}; FRAMES=[]
H={"difficulty_min":"혈풍"}; G={"difficulty_min":"겁화"}
def deep(event, hyul, geop): STORY[event]["deeper"]={"혈풍":hyul,"겁화":geop}
def add(event, choice): STORY[event]["choices"].append(choice)
def origin(key, h1, h4, g1, g4): DEEP_ORIGIN[key]={"혈풍":{"1":h1,"4":h4},"겁화":{"1":g1,"4":g4}}
def boss(key, name, who): BOSS[key]={"혈풍":{"text":f"({who}의 손바닥에 붉은 인이 박혀 있다. 혈교와 피의 계를 맺었다.)","quirks":[{"type":"bloodthirst","percent":15,"name":"혈계"}]},
  "겁화":{"text":f"({who}의 정수리에 검은 불길의 흉터가 있다. 신교 장로의 곁불을 받았다.)","quirks":[{"type":"bloodthirst","percent":15,"name":"혈계"},{"type":"barrier","percent":4,"every":5,"name":"곁불의 열기"}]}}
def frame(ending, index, req, text): FRAMES.append((ending,index,req,text))

origin("외전당가","사천의 약재 길목마다 잿빛 가사가 섰다. 혈교가 피를 받고 약을 내준다. 약재 값이 곱절로 뛰었다.","혈교와 신교가 남만의 길을 두고 다툰다. 약재를 구하러 가는 길이 싸움터를 지난다.",
 "신교가 겁화의 열을 누를 찬 약재를 쓸어 간다는 소문이 돈다. 동생에게 쓸 약재와 같은 것들이다.","곁불을 받고 타 죽어 가는 자들이 약방마다 누웠다. 찬 약재는 이제 은자로도 구하기 어렵다.")
deep("외전당가_3","좌판 사이로 잿빛 가사가 돌며 독충을 사들인다. 피에 섞어 쓴다고 한다. 마랑이 그쪽을 흘겨본다.","금섬의 독주머니 값이 석 달 새 열 곱이 되었다고 한다. 신교의 겁화전이 사들인다는 것이다. 독으로 관정의 열을 누른다고.")
deep("외전당가_4","순찰의 흰 옷에 핏자국이 있다. 혈교의 공양 행렬이 빙원 어귀까지 올라왔다고 한다.","얼음굴 앞에 검게 그을린 발자국이 있다. 곁불 받은 자들이 빙잠을 훔치러 왔다가 얼어 죽은 자리다.")
add("외전당가_3",C("잿빛 가사에게 피 한 사발을 내주고 독주머니와 바꾼다",O("혈사가 사들인 것 가운데 하나를 내 피 한 사발과 바꿨다. 손바닥에 붉은 인이 남았다. 사흘 동안 힘이 넘쳤고, 그 뒤로 가끔 손바닥이 가렵다.",alignment=AL(m=50),hp_pct=-30,stats={"external":4,"internal":3},flags=["당가_금섬","당가_혈계"]),req=H,hidden=True))
add("외전당가_4",C("얼음굴 어귀에 쓰러진 곁불 받은 자에게 실 한 가닥을 감아 준다",O("정수리가 그을린 사내의 이마에 빙잠의 실을 감자 숨이 돌아왔다. 순찰대주가 그것을 보고 있었다. \"궁의 것을 남 살리는 데 쓰는 자는 처음 본다.\" 그는 실 한 타래를 값없이 내주었다. 살아난 사내는 겁화전이 빙잠을 노리고 있다고 일러 주고 떠났다.",alignment=AL(j=70),stats={"mind":6,"internal":4},fame=15,flags=["당가_빙잠","당가_겁화"]),req=G,hidden=True))
boss("외전_오독문주","천주독모 섭홍","섭홍")
frame("외전당가_해독",1,{"flag":"당가_혈계"},"손바닥의 붉은 인은 끝내 지워지지 않았다. 동생의 독은 풀었지만 제 손의 것은 풀지 못했다.")
frame("외전당가_해독",2,{"flag":"당가_겁화"},"그해 사천의 약방에는 정수리가 그을린 환자가 줄을 섰다. 소완단은 그들에게도 들었다.")

origin("외전빙궁","빙원을 건너 처음 본 것은 고을 어귀의 피 사발이었다. 남쪽에는 불 말고도 피가 있다. 책의 첫 장에 적었다.","정마대전의 불길 옆으로 잿빛 가사의 행렬이 지나간다. 어느 편에도 서지 않는 것은 궁만이 아니었다.",
 "남쪽 하늘이 밤마다 검붉게 탄다. 궁주께서 말한 백 년 전의 불과는 다른 불이다.","겁화대가 지나간 성벽은 맨손에 무너졌다. 저 불이 빙원을 건너면 얼음 문은 얼마나 버틸까.")
deep("외전빙궁_2","객잔 구석에는 잿빛 가사의 승려도 앉아 있다. 아무에게도 잔을 권하지 않고 오가는 사람의 손바닥만 본다.","붉은 옷의 여인 뒤에 선 호위의 정수리에 검은 흉터가 있다. 그가 쥔 난간이 소리 없이 우그러진다.")
deep("외전빙궁_끝","문에서 멀찍이 떨어진 눈밭에 사람들이 웅크리고 있다. 혈교의 공양을 피해 빙원을 건너온 고을 사람들이다.","얼음 문 아래쪽이 한 뼘 녹아 있다. 남쪽의 불기운이 여기까지 왔다.")
add("외전빙궁_2",C("혈교라 적는다. 굶는 자에게 죽을 주는 쪽이 남는다",O("사절 대표의 붓이 멈췄다. \"낙양의 세 탁자 가운데 누구도 그 이름을 입에 올리지 않았다. 그래서 적을 만하다.\"",alignment=AL(m=40),stats={"mind":6},flags=["빙궁_혈교"]),req=H,hidden=True))
add("외전빙궁_4",C("겁화대가 무너뜨린 성벽 앞에서 그 불을 손바닥으로 받아 본다",O("검은 불기운이 손바닥에서 얼음과 부딪쳤다. 얼음이 이겼다. 아슬아슬했다. 책에 적었다. '겁화는 빙백으로 끌 수 있다. 한 사람 몫은.' 피난민은 그사이 북문을 다 빠져나갔다.",battle="겁화대마졸",foe="신교 선봉의 겁화대",foe_line="\"얼음이 불을 막겠다고. 녹는 소리나 들어 보자.\"",alignment=AL(j=60),stats={"internal":8,"external":4},fame=30,flags=["빙궁_북문","빙궁_겁화"]),req=G,hidden=True))
frame("외전빙궁_개문",2,{"flag":"빙궁_겁화"},"궁은 문을 넘어온 자들 가운데 정수리가 그을린 이들을 얼음굴에 눕혔다. 겁화는 빙백으로 끌 수 있다고 〈그〉의 책에 적혀 있었기 때문이다.")
frame("외전빙궁_개문",2,{"flag":"빙궁_혈교"},"궁주는 〈그〉의 책 가운데 혈교를 적은 장을 따로 묶어 두었다. 불은 꺼져도 피는 남는다는 것이다.")
frame("외전빙궁_폐문",1,{"difficulty_min":"겁화"},"닫은 문 아래 녹았던 한 뼘은 그해 겨울 다시 얼었다. 문밖의 원망은 〈그〉가 받았다.")

origin("외전매화","스승의 자리를 노리고 올라온 자들 가운데 손바닥에 붉은 인이 박힌 자가 있다. 혈교와 피의 계를 맺고 힘을 빌린 것이다.","혈계를 맺은 도전자가 늘었다. 원로들은 그런 자의 이름을 명부에 올릴 수 있는지를 두고 다툰다.",
 "산 아래에서는 정수리에 검은 흉터가 난 자가 맨손으로 성문을 부쉈다는 말이 돈다. 명부의 열 자리가 갑자기 좁아 보인다.","곁불을 받은 자들이 십대고수에게 도전장을 낸다. 오래 못 가 타 죽을 몸으로 명부에 이름을 남기려는 것이다.")
deep("외전매화_4","원로 하나가 덧붙인다. \"요즘은 혈교의 피를 빌려 도전하는 자들이 있네. 그런 자를 어찌 대하는지도 적어 두겠네.\"","원로 하나가 덧붙인다. \"곁불 받은 자들이 명부를 노리네. 곧 꺼질 불로 열 자리를 넘보는 게지. 자네가 그 불을 어찌 대하는지도 적어 두겠네.\"")
deep("외전매화_끝","무덤가 모래톱에 부러진 병기 몇 자루가 꽂혀 있다. 이 섬까지 스승을 찾아온 혈계의 도전자들이 두고 간 것이다.","섬의 누운 나무 몇 그루가 검게 탔다. 곁불 받은 도전자가 다녀간 자리다. 스승의 소매 끝도 그을려 있다.")
add("외전매화_4",C("혈계를 맺은 도전자를 원로들 앞에서 꺾고 그 손바닥을 펴 보인다",O("쓰러진 자의 손바닥에 붉은 인이 박혀 있었다. 원로들이 웅성거렸다. 제갈염이 적는다. '남의 피를 빌린 수는 수가 아니다. 이 자가 그것을 보였다.'",battle="천하도전자",foe="혈계의 도전자 구양척",foe_line="\"피를 빌렸든 불을 빌렸든 이기면 내 자리다.\"",alignment=AL(j=50),stats={"martial":7,"external":4},fame=30,flags=["매화_도전","매화_혈계꺾음"]),req=H,hidden=True))
frame("외전매화_열째",1,{"flag":"매화_혈계꺾음"},"명부에 새 법이 한 줄 생겼다. 남의 피와 남의 불을 빌린 자의 도전은 받지 않는다. 〈그〉가 올린 글이다.")
frame("외전매화_섬",1,{"difficulty_min":"겁화"},"곁불 받은 도전자들은 그 뒤로도 섬을 찾았다. 스승과 제자가 번갈아 받았다. 열째 자리는 비어 있어도 지키는 사람은 둘이었다.")

origin("외전살막","곡 노인의 서랍에 잿빛 봉투가 섞여 있다. 혈교가 맡긴 일감이다. 공양을 막는 자들의 이름이라 한다.","혈교는 값을 은자가 아니라 피의 계로 치르겠다고 한다. 살수 몇이 벌써 손바닥에 붉은 인을 받았다.",
 "살막에 처음 보는 일감이 들어왔다. 정수리에 검은 흉터가 난 자를 지워 달라는 것이다. 값이 여느 일감의 열 곱이다.","겁화대의 이름이 쪽지에 오른다. 맡긴 쪽은 맹이기도 하고, 신교 안의 누구이기도 하다.")
deep("외전살막_3","산사가 덧붙인다. \"요즘 장부에는 잿빛 먹으로 쓴 줄이 있소. 혈교의 일감이오. 막주가 직접 받는다 들었소.\"","산사가 덧붙인다. \"추살조가 곁불을 받았다는 말이 있소. 나가려는 놈을 더 빨리 지우려고.\"")
deep("외전살막_끝","조일의 칼 든 손바닥에 붉은 인이 보인다.","조일이 두건을 벗는다. 정수리에 검은 불길의 흉터가 있다.")
add("외전살막_4",C("혈교가 맡긴 잿빛 봉투를 받는다",O("공양을 막던 고을의 훈장이었다. 값은 은자가 아니라 피의 계였다. 손바닥에 붉은 인이 박히자 패 뒷면의 숫자가 저절로 지워졌다. 곡 노인이 고개를 저었다. \"그건 값을 치른 게 아니라 주인을 바꾼 거다.\"",alignment=AL(m=80),stats={"external":6,"martial":6},flags=["살막_값","살막_혈계"]),req=H,hidden=True))
boss("외전_추살수좌","무흔 조일","조일")
frame("외전살막_자유",2,{"flag":"살막_혈계"},"장부의 이름은 지웠지만 손바닥의 인은 남았다. 살막에서 나온 〈그〉를 다음에 부른 것은 잿빛 가사였다.")
frame("외전살막_소각",2,{"difficulty_min":"겁화"},"가라앉은 장부에는 겁화대의 이름도 여럿 적혀 있었다. 그들을 지워 달라던 사람들은 값을 돌려받지 못했다.")

origin("외전수로","불탄 수채 아래로 흐르는 물이 붉다. 상류의 고을 하나가 혈교의 공양에 걸렸다고 한다.","잿빛 가사를 실은 배가 밤마다 강을 오른다. 총채주가 그 뱃길을 내주고 무엇을 받았는지는 아무도 모른다.",
 "강 건너 신교의 나루에 검은 연기가 오른다. 겁화전으로 가는 숯과 쇠가 장강을 탄다.","겁화대를 실은 병선이 강을 내려온다. 그 배는 노를 젓지 않아도 물살을 거스른다고 한다.")
deep("외전수로_3","장부 끝에 잿빛 먹으로 쓴 줄이 있다고 한다. 혈교의 배를 통행세 없이 올려 보내 준 값이다.","장부 끝에 붉은 인장이 찍힌 줄이 있다고 한다. 신교의 숯배를 지켜 준 값이다. 총채주는 관아와 신교 양쪽에서 받는다.")
deep("외전수로_끝","우대강의 손바닥에 붉은 인이 박혀 있다. 뱃길을 내주고 받은 것이 그것이었다.","우대강의 정수리에 검은 흉터가 있다. 숯배를 지켜 주고 받은 것이 그것이었다.")
add("외전수로_4",C("밤에 강을 오르는 혈교의 배를 가라앉힌다",O("배 밑창에는 사발이 아니라 사람이 실려 있었다. 공양에 걸린 고을의 아이들이다. 청교채의 배가 그 아이들을 하류로 실어 날랐다. 추삼낭의 흰 돛이 말없이 뒤를 따랐다.",battle="혈교혈위대",foe="공양선을 지키는 혈위대",foe_line="\"강의 도적이 개조의 배를 막느냐. 네 피도 싣고 가마.\"",alignment=AL(j=80),stats={"external":6,"martial":5},fame=35,flags=["수로_피난","수로_추삼낭","수로_혈선"]),req=H,hidden=True))
boss("외전_총채주","물귀신 우대강","우대강")
frame("외전수로_주인",1,{"flag":"수로_혈선"},"잿빛 가사를 실은 배는 그 뒤로 청교채의 물목을 지나지 못했다. 관은 못 한 일이다.")
frame("외전수로_나눔",2,{"flag":"수로_혈선"},"공양선에서 내린 아이들 가운데 몇은 자라서 청교채의 노를 잡았다.")

origin("외전혈승","본산을 나서니 산 아래 고을마다 벌써 잿빛 가사가 서 있다. 교단은 격문을 기다리지 않고 먼저 내려왔다. 순례길에 도반이 많다. 신교의 칼도 많다.","연못을 두고 신교와 맞붙는 싸움이 해를 넘겼다. 조각을 품은 순례승은 교단에서 호법 다음으로 지켜야 할 몸이 되었다.",
 "신교의 겁화전에 불이 들어갔다고 한다. 교주께서 말했다. \"저들의 불은 영물의 기운을 훔친 것이다. 개조의 피는 훔친 것이 아니다. 서둘러라.\"","겁화대가 연못을 지킨다. 관정을 견딘 자들이다. 조각이 그 불기운을 느낄 때마다 단전에서 으르렁거린다.")
deep("외전혈승_3","비석 둘레에 잿빛 가사 몇이 쓰러져 있다. 나보다 먼저 온 도반들이다. 교단이 일찍 내려온 만큼 신교의 칼도 일찍 뽑혔다.","조장의 정수리에 검은 흉터가 있다. 곁불이다. 단전의 조각이 그 불기운에 먼저 이를 드러낸다.")
deep("외전혈승_7","골짜기에는 지난 여러 해의 싸움이 남긴 뼈가 쌓였다. 잿빛도 붉은빛도 이제 가릴 수 없다.","횃불 가운데 몇은 횃불이 아니다. 겁화대의 정수리에서 타는 불이다.")
add("외전혈승_6",C("연못가를 지키는 겁화대와 맞선다",O("관정을 견딘 몸은 단단했다. 그래도 조각 셋을 품은 몸이 더 깊었다. 쓰러진 자의 정수리에서 검은 불이 꺼지며 연못으로 빨려 들어갔다. 개조의 그릇은 남의 불도 마신다. 넷째 조각이 그 불과 함께 올라와 단전에 앉았다.",battle="겁화대마졸",foe="연못을 지키는 겁화대",foe_line="\"잿빛 쥐가 여기까지. 타는 맛을 보여 주마.\"",alignment=AL(m=50),stats={"external":8,"internal":6},full_growth=True,flags=["혈승_겁화꺾음"]),req=G,hidden=True))
